#!/usr/bin/env bash
# Generated by cs-image-system bootstrap -- sets this repository's Actions secrets
# (CI_SETUP.md 3.7). No secret VALUE is in this script, the tfvars or the state:
# each is read from a file named after the secret under the secrets directory,
# or from an output of the applied root. Run it from the repository root after
# `tofu apply` in generated/bootstrap, with `gh` logged in.
set -euo pipefail
REPO="${REPO:-infrastructurebuilder/cs-image-system-testconfig}"
DIR="${SECRETS_DIR:-_uncommitted/secrets}"
ROOT="$(cd "$(dirname "$0")" && pwd)"

from_file() {   # NAME: the file $DIR/NAME holds the value
  if [ ! -s "$DIR/$1" ]; then echo "set-secrets: $DIR/$1 is missing or empty; skipped" >&2; return 0; fi
  gh secret set "$1" --repo "$REPO" < "$DIR/$1" && echo "set-secrets: $1 set from $DIR/$1"
}
from_output() {   # NAME OUTPUT: the applied root's output holds the value
  gh secret set "$1" --repo "$REPO" --body "$(tofu -chdir="$ROOT" output -raw "$2")" && echo "set-secrets: $1 set from output $2"
}

# the READ-ONLY role's ARN, from the applied root
from_output AWS_ROLE_ARN aws_read_role_arn
# the WRITE role's ARN, from the applied root
from_output AWS_APPLY_ROLE_ARN aws_write_role_arn
# the provider's full resource name (3.4)
from_file GCP_WORKLOAD_IDENTITY_PROVIDER
# the READ-ONLY service account's address (3.4)
from_file GCP_SERVICE_ACCOUNT
# the service account that may write (3.4)
from_file GCP_APPLY_SERVICE_ACCOUNT
# the okta provider's private key, PEM (3.5)
from_file OKTA_API_PRIVATE_KEY
# the OPA service user's key (3.5)
from_file TF_VAR_KEY
# the OPA service user's secret (3.5)
from_file TF_VAR_SECRET
# CI's age identity, the whole file (3.6)
from_file CSIS_CONFIG_IDENTITY
